import os
import torch
import random
import numpy as np


class GeneralConfig:
    """Global configuration settings."""

    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 12  # Utilizing available vCPUs
    DEBUG = False
    DEBUG_DATA_LIMIT = 50  # Limit data size when debugging


class PathConfig:
    """File paths and directory structure."""

    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_9"

    # Input Metadata (Generated by previous steps)
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test_metadata.csv")
    DEPTHS_CSV = os.path.join(INPUT_DIR, "depths.csv")

    # Output Directories
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
    LOG_DIR = os.path.join(WORKING_DIR, "logs")
    SUBMISSION_DIR = os.path.join(WORKING_DIR, "submission")
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")

    @classmethod
    def create_directories(cls):
        """Creates the necessary working directories."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.CHECKPOINT_DIR, exist_ok=True)
        os.makedirs(cls.LOG_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)


class DataConfig:
    """Data processing and augmentation hyperparameters."""

    ORIG_H = 101
    ORIG_W = 101
    IMG_H = 128  # Padded height
    IMG_W = 128  # Padded width
    CHANNELS = 3  # Input: [Seismic, Seismic, Depth]

    NUM_FOLDS = 5
    BATCH_SIZE = 64

    # Augmentation Parameters
    ROTATION_LIMIT = 5
    SCALE_LIMIT = 0.05
    SHIFT_LIMIT = 0.05

    # Normalization (Standard ImageNet stats)
    MEAN = [0.485, 0.456, 0.406]
    STD = [0.229, 0.224, 0.225]


class ModelConfig:
    """Model architecture configuration."""

    ENCODER = "resnext50_32x4d"
    ENCODER_WEIGHTS = "imagenet"
    DECODER = "unetplusplus"  # Nested U-Net
    ATTENTION_TYPE = "scse"  # Spatial and Channel Squeeze & Excitation
    IN_CHANNELS = 3
    CLASSES = 1
    ACTIVATION = None  # Output logits for Lovasz/BCEWithLogits


class TrainConfig:
    """Training hyperparameters and optimization strategy."""

    EPOCHS = 80
    WARMUP_EPOCHS = 20  # Epochs to train with BCE+Dice before switching/adding Lovasz

    LR = 1e-4
    WEIGHT_DECAY = 1e-4

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 20

    # Scheduler (ReduceLROnPlateau)
    SCHEDULER_FACTOR = 0.5
    SCHEDULER_PATIENCE = 5
    MIN_LR = 1e-7

    # Optimization
    MIXED_PRECISION = True
    GRADIENT_ACCUMULATION_STEPS = 1


def seed_everything(seed=42):
    """Sets the random seed for reproducibility."""
    random.seed(seed)
    os.environ["PYTHONHASHSEED"] = str(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed(seed)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False


# Ensure directories exist when module is imported
PathConfig.create_directories()
